import okhttp3.*;
import com.sun.net.httpserver.*;
import java.net.InetSocketAddress;

public class T2 {
  public static void main(String[] a) throws Exception {
    // 起一个真会 302 的本地服务，让 OkHttp 真的跟随一次重定向
    HttpServer srv = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
    int port = srv.getAddress().getPort();
    srv.createContext("/auth", ex -> {
      ex.getResponseHeaders().add("Location",
        "http://127.0.0.1:" + port + "/game#play_token=gt1.REAL.sig");
      ex.sendResponseHeaders(302, -1); ex.close();
    });
    srv.createContext("/game", ex -> {
      byte[] b = "ok".getBytes();
      ex.sendResponseHeaders(200, b.length);
      ex.getResponseBody().write(b); ex.close();
    });
    srv.start();

    OkHttpClient c = new OkHttpClient.Builder().followRedirects(true).build();
    Request req = new Request.Builder().url("http://127.0.0.1:" + port + "/auth").build();
    try (Response res = c.newCall(req).execute()) {
      // 这就是 Android NetworkingModule.kt:649 回填 responseURL 的那个表达式
      String responseURL = res.request().url().toString();
      System.out.println("最终 code           = " + res.code());
      System.out.println("priorResponse code  = " + (res.priorResponse()!=null ? res.priorResponse().code() : "null"));
      System.out.println("responseURL         = " + responseURL);
      System.out.println("含 play_token       = " + responseURL.contains("play_token="));
      System.out.println();
      System.out.println(responseURL.contains("play_token=")
        ? "=> 【端到端实测】OkHttp 跟随 302 后 responseURL 带着 fragment ⇒ Android 侧取票可行"
        : "=> 【端到端实测】fragment 在跟随时被剥掉 ⇒ Android 侧取不到票");
    }
    srv.stop(0);
  }
}
EOF
